PBX1.status_function:
if (!message.startsWith("FE1A")) {
  return null;
}
const parts = parseHexMessage(message);
if (parts.length < 16) {
  return null;
}

const decodeTemp = (data, pos) => { 
  const encoded = data[pos] << 7 | (data[pos+1] & 0x7f);
  if (encoded == 0) {
   	return undefined;
	}
	return encoded - 8192;
}

const status = {
 grillTemp: decodeTemp(parts, 2),
grillSetTemp: decodeTemp(parts, 4),
  p1Target: decodeTemp(parts, 8),
  p2Target: decodeTemp(parts, 12),
  p1Temp: decodeTemp(parts, 6),
  p2Temp: decodeTemp(parts, 10),
  moduleIsOn: (parts[15] & 0x10) !== 0, 
  err1: false,
  err2: false,
  err3: false,
  highTempErr: (parts[14] & 0x40) !== 0,
  fanErr: (parts[14] & 0x01) !== 0,
  hotErr: (parts[14] & 0x04) !== 0,
  motorErr: (parts[14] & 0x02) !== 0,
  noPellets: (parts[14] & 0x20) !== 0,
  erL: (parts[14] & 0x08) !== 0,
  fanState: (parts[15] & 0x01) !== 0,
  hotState: (parts[15] & 0x04) !== 0,
  motorState: (parts[15] & 0x02) !== 0,
  lightState: false,
  primeState: false,
  isFahrenheit: (parts[15] & 0x08) === 0,
  recipeStep: 0,
  recipeTime: 0,
};
if (!status.isFahrenheit) {
  const ftoc = function (temp) {
    if ((typeof temp === "undefined") || (temp === 960)) {
      return temp;
    }
    return Math.floor((temp - 32) / 1.8);
  };
  status.p1Temp = ftoc(status.p1Temp);
  status.p2Temp = ftoc(status.p2Temp);
  status.p3Temp = ftoc(status.p3Temp);
  status.grillSetTemp = ftoc(status.grillSetTemp);
  status.grillTemp = ftoc(status.grillTemp);
  status.p1Target =  ftoc(status.p1Target);
  status.p2Target =  ftoc(status.p2Target);
}

return status;

